-- D-36 Waste Management Program: FSQM-037, DRAFT.
--
-- Two Non-Compliant findings, 11.8.1.1 (documented methods for dry, wet and liquid waste) and 11.8.1.6
-- (controlled disposal of trademarked material). The other eight limbs of 11.8 are judged on site, and
-- the program covers them so the observation has something to be judged against. FSQM-037 is reserved in
-- the remediation workbook.
--
-- Owner's answers, 2026-09-28: the building provides and empties a lidded dumpster outside and the site
-- holds no waste contract of its own; waste is bagged and taken out; wash water goes down the drain;
-- small amounts of syrup go down the drain and larger amounts go into containers and into the dumpster;
-- mis-printed and spoiled labels go out INTACT.
--
-- TRADEMARKED WASTE: the first draft defaced every printed item. Rewritten 2026-09-28 after the owner
-- and the Senior Site Manager pushed back - film rolls run to thousands of feet and unrolling them to
-- tear through is impractical. 11.8.1.6 asks for controlled disposal WHERE APPLICABLE and where the
-- waste is CONSIDERED HIGH-RISK, so the program carries the site's determination instead: bulk brand-only
-- packaging (film rolls, plain cartons) goes out whole; anything carrying PRODUCT IDENTITY (lot code,
-- best-by, allergen statement, a label ready to apply) is defaced first. A customer's packaging
-- agreement overrides. Everything else writes down what the site already does.
--
-- No new form. Waste is already row 11.8.1 on the monthly GMP inspection (FRM-913), which is where
-- 11.8.1.10 asks for it.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number = 'FSQM-037') then
    raise exception 'FSQM-037 already exists.';
  end if;
  if (select count(*) from public.sop_documents
       where sop_number in ('FRM-913', 'FRM-007', 'FRM-206', 'FSQM-012', 'FSQM-032', 'FSQM-035', 'FSQM-009')
         and status = 'active') <> 7 then
    raise exception 'a document D-36 names is missing or not active.';
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-037', 'Waste Management Program', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '11.8.1.1, 11.8.1.2, 11.8.1.3, 11.8.1.4, 11.8.1.5, 11.8.1.6, 11.8.1.8, 11.8.1.9, 11.8.1.10', true, $q${"purpose": "This program states how Adventure Bakery collects, holds and disposes of its waste - dry, wet and liquid - so that waste never contaminates product, packaging or the areas they are in, and never attracts pests.", "scope": "All waste from the production, packaging and storage areas and from cleaning: trimmings and rejected product, used packaging, spoiled labels and printed packaging, empty containers, and liquid waste. Chemical containers are disposed of under FSQM-032.", "definitions": "Trademarked material: anything carrying a customer brand or product name - labels, printed film, cartons and master cases.\nProduct identity: a lot code, best-by date, allergen statement, or a label ready to apply. It is identity, not the brand, that makes trademarked waste high-risk here.\nWaste accumulation area: the lidded dumpster outside, provided and serviced by the building.", "responsibility": "Production staff - keep waste in the bins provided, take it out at the end of each run and at the end of the day, and deface anything carrying product identity before it goes out.\nManagement team - keeps the bins serviceable, and raises anything the building's waste service is not doing with the landlord.\nSQF Practitioner - checks waste handling and the dumpster area on the monthly GMP inspection.", "procedure": ["Waste inside the building", "• Each production and packaging area has a bin for its waste. Bins are lined, are emptied before they are full, and are not allowed to stand full overnight (SQF 11.8.1.2).", "• Bins that hold food waste are kept covered when not in use.", "• Every bin is lined, and the liner is replaced each time the bin is emptied, so waste does not touch the bin itself.", "• Dry waste: trimmings, rejected or damaged product, empty ingredient packaging, spoiled pouches, and used packaging materials (SQF 11.8.1.5).", "• Waste is never put on a product-contact surface, never sits on a stock rack, and never travels through the dry storage room with open product.", "• A bin is washed and sanitised when it needs it - when a liner leaks or splits, when anything is spilled into the bin, and whenever it is found soiled - not to a schedule (SQF 11.8.1.4).", "> THE LINER IS THE CONTROL AND THE INSPECTION IS WHAT MAKES IT REGULAR. 11.8.1.4 asks for collection bins to be cleaned and sanitised regularly. Here waste does not touch the bin, so washing on a calendar would clean bins that are already clean and would still miss the one that a split liner soiled on the day after it was washed. Instead every bin is looked at on the monthly GMP inspection, and one that is soiled is washed then and the finding recorded. Condition decides, and the inspection is what stops 'as necessary' from meaning 'never'.", "Taking waste out", "• Waste goes out at the end of each run and at the end of the day, bagged and tied, into the lidded dumpster outside (SQF 11.8.1.1, 11.8.1.2).", "• The dumpster is provided and emptied by the building's waste service, not by a contract the site holds. The site's part is to keep its own waste bagged and the lid closed, and to tell the landlord if the dumpster is overfull or not being emptied (SQF 11.8.1.6).", "• The lid stays closed. An open dumpster beside a food plant is a pest attractant, and the dumpster stands away from the doors (SQF 11.8.1.8).", "• Anyone handling waste washes their hands before returning to production (FSQM-012).", "Liquid waste", "• Wash water from cleaning goes to the sink and the floor drain (SQF 11.8.1.3, 11.8.1.9).", "• Small amounts of leftover syrup go down the drain with plenty of water behind them. Larger amounts go into a closed container, and the closed container goes into the dumpster - never a loose or open container, and never poured out where it can stand (SQF 11.8.1.9).", "• No liquid waste is held on site overnight in an open container.", "Trademarked material - what is high-risk here, and what is not", "> 11.8.1.6 asks for controlled disposal of trademarked waste WHERE APPLICABLE and where it is CONSIDERED HIGH-RISK for handling or other reasons. The site decides which of its trademarked waste that is, and this Part is that decision.", "• NOT HIGH-RISK, and disposed of as ordinary waste: bulk printed packaging that carries brand artwork only and no product identity - film rolls, plain printed cartons and master cases. It goes out whole, in the dumpster or to recycling, with nothing done to it first.", "> WHY. To misuse a roll of printed film somebody would need the same product, the same machine and the same customer, and the roll carries no lot code, no best-by date and no allergen statement. Unrolling hundreds or thousands of feet to tear through it would be a gesture, not a control, and a control nobody can perform is one the site would be found not performing.", "• HIGH-RISK, and defaced before it goes out: anything carrying PRODUCT IDENTITY - a lot code, a best-by date, an allergen statement or a label ready to apply. Spoiled and mis-printed labels, coded cartons and coded master cases are torn or marked through the code and the brand so they cannot be read or re-used (SQF 11.8.1.6).", "> WHY THESE ARE DIFFERENT. Identity is the part that can be reapplied: a printed label carrying a customer's brand and a lot code can be taken out of a shared dumpster and put on something the site never made, and it is a traceability exercise's worst answer. Defacing one takes a second, which is the whole argument for keeping it.", "• A CUSTOMER'S PACKAGING AGREEMENT OVERRIDES this determination. Where a customer requires their branded material to be destroyed or returned, that is done for that customer and their instruction is kept with the agreement.", "• This determination is reviewed when the packaging changes, when a customer sets a requirement, and with the food defence and food fraud assessment, which looks at counterfeit packaging from the other direction.", "What does not apply here", "• No waste leaves this site as animal feed, so no denaturant is used and 11.8.1.7 does not engage.", "• The site holds no waste disposal contract of its own; the building's service collects. If the site ever contracts one, its performance is reviewed at least annually and recorded on FRM-206 (SQF 11.8.1.6).", "Checks and review", "• Waste handling, the bins and the dumpster area are checked on the monthly GMP inspection (FRM-913, row 11.8.1), and anything found is recorded and corrected there (SQF 11.8.1.10, 2.5.4.3).", "• A repeated finding - an overflowing dumpster, waste left standing, labels going out intact - is raised as a corrective action on FRM-007 under FSQM-009."], "form_references": "FRM-913 - GMP / Food Safety Inspection Record (row 11.8.1, waste)\nFRM-007 - Corrective and Preventive Action record\nFRM-206 - Contract Services Register (only if the site ever contracts a waste service)", "records": "This program creates no record of its own. Waste is evidenced by the monthly GMP inspection on FRM-913 and by any corrective action raised on FRM-007.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 11.8.1.1 to 11.8.1.10 (Waste Disposal).\n\nFSQM-012 Good Manufacturing Practices Program and FRM-913 - the monthly inspection that checks waste.\nFSQM-032 Chemical Control Program - empty chemical containers, which are rinsed and disposed of under that program, not this one.\nFSQM-035 Receipt, Storage and Handling Program - the storage areas waste must not travel through.\nFSQM-009 CAPA - repeated findings.", "revision_history": "New - 2026-09-28 - DRAFT under D-36, for the two Non-Compliant findings against 11.8.1.1 and 11.8.1.6, and covering the eight limbs of 11.8 that are judged by observation on site.\n\nWHAT THE SITE DOES NOW (owner, 2026-09-28): waste is bagged and taken out to a lidded dumpster outside, provided and emptied by the building's waste service - the site holds no waste contract of its own. Wash water goes down the drain; small amounts of leftover syrup go down the drain, and larger amounts go into containers and into the dumpster.\n\nTRADEMARKED WASTE IS RISK-ASSESSED RATHER THAN DESTROYED WHOLESALE (owner and Senior Site Manager, 2026-09-28). The first draft had every piece of printed packaging defaced before disposal. Gabriela pushed back: nobody she has encountered with SQF certification unrolls film to tear it, and the site holds rolls running to thousands of feet. She is right, and 11.8.1.6 is narrower than that draft read it - it asks for controlled disposal WHERE APPLICABLE and where the waste is CONSIDERED HIGH-RISK, which is a determination the site makes.\n\nTHE DETERMINATION: bulk printed packaging carrying brand artwork only - film rolls, plain cartons and cases - is NOT high-risk and goes out whole as ordinary waste. Anything carrying PRODUCT IDENTITY - a lot code, best-by date, allergen statement, or a label ready to apply - IS high-risk and is defaced first, because identity is the part that can be reapplied to product this site never made. Defacing a label takes a second; unrolling a film roll is a gesture nobody would perform twice, and a control nobody performs is one the site is found not performing.\n\nA CUSTOMER'S PACKAGING AGREEMENT OVERRIDES the determination. Worth checking what the customers' agreements say, because a contractual destruction requirement is the usual reason a plant destroys packaging - not the code.\n\nThe determination is revisited with the food defence and food fraud assessment (D-22), which looks at counterfeit packaging from the other side.\n\nBIN WASHING IS BY CONDITION, NOT BY SCHEDULE (owner, 2026-09-28): the bins are lined, so waste does not touch them, and the owner asked not to carry a scheduled wash. 11.8.1.4's word is 'regularly', and what makes it regular here is the monthly GMP inspection: every bin is looked at, and a soiled one is washed and the finding recorded. If an auditor presses on it, that is the answer - the liner is the control, the inspection is the frequency.\n\nNO NEW FORM: waste is already a row on the monthly GMP inspection (FRM-913, row 11.8.1), which is where 11.8.1.10 asks for it. A separate waste record would be a second account of one activity."}$q$::jsonb);

do $verify$
declare p jsonb;
begin
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-037';
  if jsonb_array_length(p) <> 31 then raise exception 'FSQM-037 procedure is % lines, expected 31.', jsonb_array_length(p); end if;
  if (select count(*) from jsonb_array_elements_text(p) l where l like '%NOT HIGH-RISK, and disposed of as ordinary waste%') <> 1
     or (select count(*) from jsonb_array_elements_text(p) l where l like '%HIGH-RISK, and defaced before it goes out%') <> 1 then
    raise exception 'the trademarked-material determination is missing a limb.';
  end if;
  if (select count(*) from jsonb_array_elements_text(p) l where l like '%PACKAGING AGREEMENT OVERRIDES%') <> 1 then
    raise exception 'the customer-agreement override is missing.';
  end if;
end $verify$;

commit;
